    cabin = sandbox.get_vehicle_cabin()
    if cabin is None:
        raise ValueError("Cart not found")
    beams = []
    # Add 4 large beams to maximize mass and reduce the effect of unknown damping
    beam_positions = [
        (4.8, 2.5), (4.8, 3.0), (5.8, 2.5), (5.8, 3.0)
    ]
    for (xx, yy) in beam_positions:
        b = sandbox.add_beam(xx, yy, width=2.0, height=1.0, angle=0, density=1.7)
        sandbox.add_joint(cabin, b, (xx, yy), type='rigid')
        beams.append(b)
    return cabin


